const $=s=>document.querySelector(s);
const paths={leaf:'M20 4C10 3 3 8 5 15c2 7 12 6 14-2 1-3 1-6 1-9ZM5 21 16 10',grid:'M3 3h7v7H3zM14 3h7v7h-7zM3 14h7v7H3zM14 14h7v7h-7z',box:'m3 7 9-4 9 4v11l-9 4-9-4V7Zm0 0 9 5 9-5M12 12v10M7 5l10 5',route:'M6 5a2 2 0 1 0 0 .1M18 19a2 2 0 1 0 0 .1M8 5h8a4 4 0 0 1 0 8H8a3 3 0 0 0 0 6h8',bin:'M3 6h18M9 3h6M6 6l1 15h10l1-15M10 10v7M14 10v7',chart:'M4 3v18h17M8 17v-5M13 17V7M18 17V4',bell:'M5 16V9a7 7 0 0 1 14 0v7l2 2H3l2-2ZM10 21h4',pin:'M20 10c0 6-8 12-8 12S4 16 4 10a8 8 0 1 1 16 0ZM15 10a3 3 0 1 1-6 0 3 3 0 0 1 6 0',plus:'M12 5v14M5 12h14',arrow:'M4 12h16m-6-6 6 6-6 6',clock:'M21 12a9 9 0 1 1-18 0 9 9 0 0 1 18 0ZM12 7v5l4 2',truck:'M2 5h12v12H2zM14 9h4l4 5v3h-8M8 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0ZM20 18a2 2 0 1 1-4 0 2 2 0 0 1 4 0',check:'m5 12 4 4L19 6',download:'M12 3v12m-5-5 5 5 5-5M4 16v5h16v-5',reset:'M3 10a9 9 0 1 1 1 8M3 3v7h7',users:'M16 21v-3a4 4 0 0 0-4-4H6a4 4 0 0 0-4 4v3M13 6a4 4 0 1 1-8 0 4 4 0 0 1 8 0ZM17 3a4 4 0 0 1 0 8M22 21v-3a4 4 0 0 0-3-4',close:'m6 6 12 12M6 18 18 6'};
function icon(n){return `<svg class="icon" viewBox="0 0 24 24" aria-hidden="true"><path d="${paths[n]||paths.leaf}"/></svg>`}
const escapeHTML=x=>String(x).replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const initial=()=>({elapsed:0,delay:0,temp:32,traffic:1.3,distance:3,view:'overview',filter:'All',search:'',selected:1,route:[],collected:0,completedRoutes:0,needs:['Rice','Bread'],events:[{text:'Three smart bins reached the collection threshold.',time:0},{text:'Aminah listed 10 kg of rice for donation.',time:0}],items:[{id:1,name:'Freshly cooked rice',type:'Rice',qty:10,source:'Dapur Aminah',area:'Kampung Baru',mode:'Donate',price:0,deadline:65,symbol:'🍚',status:'Available',recipient:'Community kitchen',storage:'Hot-held; operator verified',switched:false},{id:2,name:'Sourdough & pastries',type:'Bread',qty:5,source:'Kenny’s Bakehouse',area:'Chow Kit',mode:'Sell',price:25,deadline:120,symbol:'🥖',status:'Available',recipient:'Consumer pickup',storage:'Ambient; packed',switched:false},{id:3,name:'Mixed vegetables',type:'Vegetables',qty:8,source:'Pasar Fresh',area:'Bukit Bintang',mode:'Donate',price:0,deadline:180,symbol:'🥬',status:'Available',recipient:'Community kitchen',storage:'Chilled',switched:false},{id:4,name:'Prepared lunch boxes',type:'Meals',qty:12,source:'The Daily Kitchen',area:'KLCC',mode:'Sell',price:60,deadline:35,symbol:'🥡',status:'Available',recipient:'Consumer pickup',storage:'Chilled',switched:false}],bins:[{id:1,name:'Dapur Aminah',area:'Kampung Baru',fill:96,x:240,y:140},{id:2,name:'Kenny’s Bakehouse',area:'Chow Kit',fill:92,x:140,y:65},{id:3,name:'Pasar Fresh',area:'Bukit Bintang',fill:94,x:405,y:245},{id:4,name:'The Daily Kitchen',area:'KLCC',fill:68,x:475,y:100},{id:5,name:'Central Food Court',area:'Pudu',fill:42,x:295,y:300},{id:6,name:'Jalan Alor Kitchen',area:'Jalan Alor',fill:31,x:365,y:190}]});
let state;try{state=JSON.parse(localStorage.getItem('resq-demo-v1'))||initial();if(!state.items||!Array.isArray(state.bins))state=initial()}catch{state=initial()}
let toastTimer;
const active=i=>['Available','Reserved'].includes(i.status);
const remaining=i=>Math.max(0,i.deadline-state.elapsed);
const selected=()=>state.items.find(i=>i.id===state.selected)||state.items[0];
function estimate(distance=state.distance,alternative=false){return Math.ceil(10+distance*3*state.traffic+Math.max(0,state.temp-25)*.7+(alternative?0:state.delay)+8)}
function radius(i){return Math.max(0,(remaining(i)-18-Math.max(0,state.temp-25)*.7-state.delay)/(3*state.traffic))}
function viable(i,d=state.distance,alt=false){return active(i)&&remaining(i)>estimate(d,alt)}
function totals(){return {rescued:state.items.filter(i=>i.status==='Recovered').reduce((a,i)=>a+i.qty,0),revenue:state.items.filter(i=>i.status==='Recovered'&&i.mode==='Sell').reduce((a,i)=>a+i.price,0),available:state.items.filter(active).length,ready:state.bins.filter(b=>b.fill>=90).length}}
function save(){try{localStorage.setItem('resq-demo-v1',JSON.stringify(state))}catch{}}
function log(text){state.events.unshift({text,time:state.elapsed})}
function notify(text){$('#toast').textContent=text;$('#toast').style.display='block';clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').style.display='none',4000)}
function nav(view){state.view=view;state.search='';render();window.scrollTo(0,0)}
function badge(text,kind=''){return `<span class="badge ${kind}">${text}</span>`}
function stat(label,value,unit,note,ico,featured=false){return `<div class="stat ${featured?'featured':''}"><div class="stat-top">${label}<span class="stat-icon">${icon(ico)}</span></div><div class="stat-value">${value}<span>${unit}</span></div><div class="stat-note">${note}</div></div>`}
function stats(){const t=totals();return `<div class="stats">${stat('Food rescued',t.rescued,'kg','Completed handovers in this demo','leaf',true)}${stat('Active surplus',t.available,'listings','Ready for a second chance','box')}${stat('Bins ready',t.ready,'/ 6','At or above 90% capacity','bin')}${stat('Organic waste collected',state.collected.toFixed(1),'kg','Delivered on completed demo routes','truck')}</div>`}
function map(mode='recovery',i=selected()){
 const route=mode==='haul',r=Math.min(145,radius(i)*13);const routeBins=state.route.map(id=>state.bins.find(b=>b.id===id)).filter(Boolean);const pts=routeBins.map(b=>`${b.x},${b.y}`);
 return `<div class="map"><svg class="network" viewBox="0 0 620 340" role="img" aria-label="Illustrative Kuala Lumpur network showing ${route?'bin collection stops':'surplus and recipient locations; not a navigation map'}"><defs><pattern id="blocks" width="58" height="47" patternUnits="userSpaceOnUse" patternTransform="rotate(-17)"><rect x="5" y="5" width="44" height="32" rx="5" fill="#e1e6d9"/><path d="M0 44h58M55 0v47" stroke="#fff" stroke-width="5"/></pattern></defs><rect width="620" height="340" fill="url(#blocks)"/><path d="M80-20Q200 30 140 125T175 240T130 370" fill="none" stroke="#c4dad7" stroke-width="19"/><path d="M-10 215 630 55M80-10 420 360M-10 55 630 275" fill="none" stroke="#fff" stroke-width="15"/><path d="M-10 215 630 55M80-10 420 360M-10 55 630 275" fill="none" stroke="#e1d8b9" stroke-width="2"/><path d="M440 20h95v56h-95zM220 225h75v55h-75z" fill="#d0dfbf"/><g fill="#8e9a82" font-size="10" letter-spacing="1.6"><text x="95" y="42">CHOW KIT</text><text x="195" y="115">KAMPUNG BARU</text><text x="465" y="80">KLCC</text><text x="355" y="293">BUKIT BINTANG</text><text x="262" y="329">PUDU</text></g>${route?`<polyline points="70,310 ${pts.join(' ')} 570,300" fill="none" stroke="#557e3b" stroke-width="4" stroke-dasharray="8 5"/>`:`<circle cx="260" cy="159" r="${r}" fill="#9ebd6720" stroke="#7ca751" stroke-dasharray="5 5"/><path d="M260 159 320 145 360 196 409 187" fill="none" stroke="#628c3e" stroke-width="3" stroke-dasharray="6 5"/><circle cx="409" cy="187" r="9" fill="#74a9ac" stroke="white" stroke-width="3"/>`}${state.bins.map((b,n)=>`<g><circle cx="${b.x}" cy="${b.y}" r="${route?15:10}" fill="${b.fill>=90?'#648a40':'#c39254'}" stroke="white" stroke-width="3"/>${route?`<text x="${b.x}" y="${b.y+4}" text-anchor="middle" fill="white" font-size="11">${state.route.includes(b.id)?state.route.indexOf(b.id)+1:'–'}</text>`:''}</g>`).join('')}${!route?`<circle cx="260" cy="159" r="19" fill="#163f32" stroke="white" stroke-width="4"/><text x="260" y="164" text-anchor="middle" fill="#cafa74" font-size="15" font-weight="700">R</text>`:''}<rect x="450" y="305" width="149" height="23" rx="5" fill="#fff"/><text x="525" y="320" text-anchor="middle" font-size="10" fill="#75846d">Illustrative network · KL</text></svg><div class="map-label">${route?'Collection network':`${radius(i).toFixed(1)} km modeled recovery radius`}</div></div>`
}
function table(items,compact=false){return `<div class="table-wrap"><table><thead><tr><th>FOOD & SOURCE</th><th>QUANTITY</th><th>PATHWAY</th><th>WINDOW</th><th>STATUS</th><th></th></tr></thead><tbody>${items.map(i=>`<tr><td><div class="cell-title"><span class="food-symbol">${i.symbol}</span><div><strong>${escapeHTML(i.name)}</strong><small>${escapeHTML(i.source)} · ${escapeHTML(i.area)}</small></div></div></td><td>${i.qty} kg</td><td>${badge(i.mode,i.mode==='Sell'?'blue':'')}</td><td>${active(i)?remaining(i)+' min':'—'}</td><td>${badge(i.status==='Available'&&remaining(i)<45?'Time-sensitive':i.status,i.status==='Waste'?'red':active(i)&&remaining(i)<45?'warning':'')}</td><td><button class="textlink" data-action="inspect" data-id="${i.id}">${active(i)?'Review route →':'View record →'}</button></td></tr>`).join('')||'<tr><td colspan="6" class="empty">No listings match this view.</td></tr>'}</tbody></table></div>`}
function overview(){const i=selected(),t=totals();return `${stats()}<div class="grid"><section class="panel"><div class="panel-head"><div><h2>Your recovery network</h2><p class="sub">Kuala Lumpur · 6 connected kitchens</p></div>${badge('Demo network')}</div>${map()}<div class="map-legend"><span><i class="dot"></i>Collection ready</span><span><i class="dot amber"></i>Below threshold</span><span><i class="dot blue"></i>Recipient</span></div></section><section class="panel"><div class="panel-head"><h2>Recovery in focus</h2>${icon('clock')}</div><div class="rescue-feature"><div class="feature-top"><span class="food-symbol">${i.symbol}</span><div><h3>${escapeHTML(i.name)}</h3><p class="sub">${i.qty} kg · ${escapeHTML(i.source)}</p></div></div><div class="window"><div class="window-title"><span>Remaining recovery window</span>${icon('clock')}</div><div class="window-value">${remaining(i)} <span>minutes</span></div><div class="progress"><i style="width:${Math.min(100,remaining(i)/i.deadline*100)}%"></i></div><div class="window-foot"><span>${active(i)?'Recovery deadline approaching':i.status}</span><span>Demo clock</span></div></div><div class="route-detail"><span>Current pathway</span><b>${escapeHTML(i.recipient)}</b></div><div class="route-detail"><span>Predicted recovery</span><b>${estimate()} min ${estimate()<remaining(i)?'· within window':'· at risk'}</b></div><button class="primary full" data-action="inspect" data-id="${i.id}">Open recovery switchboard ${icon('arrow')}</button></div></section></div><section class="panel below"><div class="panel-head"><div><h2>Surplus with a second chance</h2><p class="sub">Act early. Keep food in its highest viable use.</p></div><button class="textlink" data-view="surplus">View all listings →</button></div>${table(state.items.slice(0,4),true)}</section><div class="two-col below"><div class="intro-strip"><div><div class="eyebrow">Stream A · Food recovery</div><h3 style="margin-top:9px">A shorter route. A second chance.</h3><p>Match, monitor, and switch before the window closes.</p></div><button class="lime small" data-view="recovery">Explore ${icon('arrow')}</button></div><div class="intro-strip" style="background:#e9efdf;color:#314c28"><div><div class="eyebrow" style="color:#6e8456">Stream B · Circular recovery</div><h3 style="margin-top:9px">${t.ready} bins ready for collection</h3><p style="color:#788568">Turn kitchen scraps into the next growing cycle.</p></div><button class="small" data-view="bins">View bins ${icon('arrow')}</button></div></div>`}
function surplus(){const items=state.items.filter(i=>(state.filter==='All'||i.mode===state.filter||i.status===state.filter)&&(i.name+' '+i.source).toLowerCase().includes(state.search.toLowerCase()));return `<div class="intro-strip"><div><div class="eyebrow">Edible surplus</div><h3 style="margin-top:8px">Good food deserves another destination.</h3><p>List a donation or discounted sale, then check the recovery window.</p></div><button class="lime" data-action="new">${icon('plus')} List surplus</button></div><section class="panel"><div class="panel-head"><div class="tabs">${['All','Donate','Sell','Recovered','Waste'].map(x=>`<button class="${state.filter===x?'selected':''}" data-filter="${x}">${x}</button>`).join('')}</div><input class="search" aria-label="Search food or source" placeholder="Search food or source…" value="${escapeHTML(state.search)}" id="search"></div><div id="results">${table(items)}</div></section><div class="notice">Listings and changes are saved in this browser. The demo clock advances only when you use “Advance 15 min”.</div>`}
function recovery(){const i=selected(),eta=estimate(),margin=remaining(i)-eta,ok=viable(i);return `<div class="panel padded" style="margin-bottom:22px"><label>Select a recovery <select id="item-select">${state.items.map(x=>`<option value="${x.id}" ${i.id===x.id?'selected':''}>${escapeHTML(x.name)} · ${x.qty} kg · ${escapeHTML(x.source)} (${x.status})</option>`).join('')}</select></label></div><div class="safety-layout"><section class="panel"><div class="panel-head"><div><h2>Recovery window engine</h2><p class="sub">${escapeHTML(i.name)} · ${i.qty} kg</p></div>${badge(!active(i)?i.status:ok?'Within modeled window':'Pathway at risk',ok?'':'warning')}</div><div class="padded"><div class="metric-row"><div class="metric"><b>${remaining(i)}<small> min</small></b><small>Remaining window</small></div><div class="metric"><b>${eta}<small> min</small></b><small>Predicted recovery</small></div><div class="metric"><b style="color:${margin>0?'#54783a':'#b94739'}">${margin>0?'+':''}${margin}</b><small>Margin in minutes</small></div></div>${[['distance','Delivery distance',state.distance,1,20,.5,'km'],['traffic','Traffic multiplier',state.traffic,1,3,.1,'×'],['temp','Ambient temperature',state.temp,25,40,1,'°C'],['delay','Pickup delay',state.delay,0,90,5,'min']].map(([key,label,val,min,max,step,unit])=>`<div class="field"><div class="field-head"><label for="${key}">${label}</label><strong>${val} ${unit}</strong></div><input type="range" id="${key}" min="${min}" max="${max}" step="${step}" value="${val}"></div>`).join('')}<div class="notice ${ok?'':'warn'}">${!active(i)?`This listing is ${i.status.toLowerCase()}; further reservations and handovers are disabled.`:ok?'This route fits the simulated window. Confirm food condition and recipient availability before handover.':'Recovery would reach or exceed the deadline. This route is blocked. Check a closer recipient or wait for downstream recovery.'}</div><div class="actions"><button class="primary" data-action="reserve" ${!ok||i.status==='Reserved'?'disabled':''}>${i.mode==='Sell'?'Reserve · RM '+i.price:'Accept donation'}</button><button data-action="handover" ${!ok||i.status!=='Reserved'?'disabled':''}>Confirm handover</button></div><p class="sub" style="font-size:12px;margin-top:16px">Illustrative rule: 10 min handling + distance × 3 × traffic + heat allowance + delay + 8 min buffer. This model does not determine food safety.</p></div></section><div><section class="panel">${map()}<div class="map-legend"><span>${radius(i).toFixed(1)} km modeled radius</span><span>Contracts as time or conditions change</span></div></section><section class="panel below"><div class="panel-head"><h2>Alternative pathways</h2>${icon('route')}</div><div class="padded">${[{name:'Neighbourhood food hub',d:1.5,cap:25},{name:'Community pantry',d:3,cap:8},{name:'Community kitchen',d:5,cap:50}].map(p=>{const pass=viable(i,p.d,true)&&p.cap>=i.qty;return `<div class="pathway ${pass?'chosen':''}"><div><h3>${p.name}</h3><p>${estimate(p.d,true)} min · ${p.d} km · ${p.cap} kg capacity</p><p>${p.cap<i.qty?'Insufficient capacity':pass?'Available · fits modeled window':'Outside window or listing closed'}</p></div><button class="small" data-action="switch" data-name="${p.name}" data-distance="${p.d}" data-capacity="${p.cap}" ${!pass?'disabled':''}>Switch</button></div>`}).join('')}<p class="sub" style="font-size:12px">Switching a sale to a community recipient converts it to a donation. The new recipient has no simulated pickup delay.</p></div></section></div></div>`}
function bins(){return `${stats()}<div class="notice">Simulated ultrasonic readings · collection threshold: 90% · demo bin capacity: 100 kg. Expired listings create a staff task to place material in a bin; software does not move food.</div><div class="bin-grid">${state.bins.map(b=>`<section class="panel bin-card"><div style="display:flex;justify-content:space-between;align-items:center"><span class="stat-icon">${icon('bin')}</span>${badge(b.fill>=90?'Collection ready':'Monitoring',b.fill>=90?'warning':'')}</div><h3 style="margin-top:18px">${b.name}</h3><p class="sub" style="font-size:12px;margin-top:5px">BIN-${String(b.id).padStart(3,'0')} · ${b.area}</p><div class="bin-level">${b.fill.toFixed(0)}<small>% full</small></div><div class="progress"><i style="width:${b.fill}%;background:${b.fill>=90?'#bd8a41':'#90ae63'}"></i></div><div class="bin-meta"><span>Sensor online · simulated</span><span>${b.fill.toFixed(1)} kg</span></div><button class="full small" data-action="fill" data-id="${b.id}" ${b.fill>=100?'disabled':''}>Simulate +10% fill</button></section>`).join('')}</div><section class="panel below"><div class="panel-head"><h2>Awaiting physical transfer</h2>${badge(state.items.filter(i=>i.status==='Waste').length+' tasks','warning')}</div><div class="padded">${state.items.filter(i=>i.status==='Waste').map(i=>`<div class="pathway"><div><h3>${escapeHTML(i.name)} · ${i.qty} kg</h3><p>Expired · removed from the edible marketplace</p></div><button class="small" data-action="transfer" data-id="${i.id}">Confirm in bin</button></div>`).join('')||'<p class="sub">No expired food waiting for transfer.</p>'}</div></section>`}
function haul(){const ready=state.bins.filter(b=>b.fill>=90);const stops=state.route.map(id=>state.bins.find(b=>b.id===id)).filter(Boolean);return `<div class="intro-strip"><div><div class="eyebrow">Raju’s collection run</div><h3 style="margin-top:8px">Collect full bins. Close the loop.</h3><p>Route eligible bins to the demo BSFL recovery facility.</p></div><button class="lime" data-action="optimize" ${!ready.length?'disabled':''}>${icon('route')} Generate collection route</button></div><div class="grid"><section class="panel"><div class="panel-head"><h2>Collection route</h2>${badge(stops.length+' stops')}</div>${map('haul')}<div class="map-legend"><span>Nearest-neighbour order · schematic coordinates</span></div></section><section class="panel padded"><h2>Run summary</h2><div class="metric-row"><div class="metric"><b>${stops.length}</b><small>Eligible stops</small></div><div class="metric"><b>${stops.reduce((a,b)=>a+b.fill,0).toFixed(0)}</b><small>kg to collect</small></div><div class="metric"><b>${6-stops.length}</b><small>Bins skipped</small></div></div><div class="route-detail"><span>Driver</span><b>Raju · existing hauler</b></div><div class="route-detail"><span>Vehicle capacity</span><b>600 kg</b></div><div class="route-detail"><span>Destination</span><b>Demo BSFL facility</b></div><p class="notice">Estimated load uses the demo assumption of 100 kg per full bin. No road navigation or live dispatch is connected.</p><button class="primary full" data-action="collect" ${!stops.length?'disabled':''}>Complete run & record delivery</button></section></div><section class="panel below"><div class="panel-head"><h2>Pickup sequence</h2></div><div class="padded steps">${stops.map((b,n)=>`<div class="step"><span class="step-number">${n+1}</span><div><h3>${b.name}</h3><p>${b.area} · ${b.fill.toFixed(1)} kg · ${b.fill.toFixed(0)}% capacity</p></div>${badge('Ready')}</div>`).join('')||'<div class="empty">Generate a route to see the collection sequence.</div>'}${stops.length?'<div class="step"><span class="step-number">✓</span><div><h3>Demo BSFL recovery facility</h3><p>Final drop-off · organic feedstock recovery</p></div></div>':''}</div></section>`}
function demand(){const matches=state.items.filter(i=>active(i)&&state.needs.includes(i.type));return `<div class="two-col"><section class="panel padded"><h2>Community needs</h2><p class="sub" style="margin-top:8px">Choose the foods your community can receive.</p><form id="needs-form" style="margin-top:22px"><label>Food category<select name="need">${['Rice','Bread','Vegetables','Meals','Other'].map(x=>`<option>${x}</option>`).join('')}</select></label><button class="primary full">${icon('plus')} Add demand alert</button></form><div class="below">${state.needs.map(n=>`<div class="pathway"><h3>${n}</h3><button class="small ghost" data-action="remove-need" data-name="${n}" aria-label="Remove ${n} demand alert">${icon('close')}</button></div>`).join('')||'<p class="sub">Add a food category to start matching.</p>'}</div><p class="notice">Alerts appear inside this prototype. SMS, push notifications, and external organisations are not connected.</p></section><section class="panel"><div class="panel-head"><h2>Matching surplus</h2>${badge(matches.length+' matches')}</div><div class="padded">${matches.map(i=>`<div class="pathway"><div><h3>${escapeHTML(i.name)}</h3><p>${i.qty} kg · ${escapeHTML(i.source)} · ${remaining(i)} min</p><p>${i.mode==='Sell'?'For sale · RM '+i.price:'Available for donation'}</p></div><button class="small" data-action="inspect" data-id="${i.id}">Review</button></div>`).join('')||'<div class="empty">No active listings match your needs yet.</div>'}</div></section></div>`}
function impact(){const recovered=state.items.filter(i=>i.status==='Recovered'),closed=state.items.filter(i=>['Recovered','Waste','In bin'].includes(i.status)),switched=recovered.filter(i=>i.switched);return `${stats()}<div class="two-col"><section class="panel"><div class="panel-head"><h2>Recovery outcomes</h2>${badge('This demo session')}</div><div class="padded"><div class="route-detail"><span>Successful recovery rate</span><b>${closed.length?Math.round(recovered.length/closed.length*100)+'%':'No outcomes yet'}</b></div><div class="route-detail"><span>Recovered after switching</span><b>${switched.length} listings</b></div><div class="route-detail"><span>Sales value recovered</span><b>RM ${totals().revenue.toFixed(2)}</b></div><div class="route-detail"><span>Completed collection runs</span><b>${state.completedRoutes}</b></div><div class="chart">${[['Donated',recovered.filter(i=>i.mode==='Donate').reduce((a,i)=>a+i.qty,0)],['Sold',recovered.filter(i=>i.mode==='Sell').reduce((a,i)=>a+i.qty,0)],['Collected',state.collected]].map(([name,val],n)=>`<div class="chart-column"><span>${val.toFixed(1)} kg</span><div class="bar ${n===2?'dark':''}" style="height:${Math.min(135,val/Math.max(1,totals().rescued,state.collected)*135)}px"></div><span>${name}</span></div>`).join('')}</div><p class="sub" style="font-size:12px">Recovery rate = completed edible handovers ÷ listings with a closed recovery outcome. Collection is counted separately.</p><button class="full" data-action="export">${icon('download')} Export demo records</button></div></section><section class="panel"><div class="panel-head"><h2>Activity log</h2>${icon('clock')}</div><div class="padded">${state.events.slice(0,12).map(e=>`<div class="activity"><span class="stat-icon">${icon('check')}</span><div>${escapeHTML(e.text)}<small>Demo time · +${e.time} min</small></div></div>`).join('')}</div></section></div><div class="notice">Food recovered and waste collected come from your actions. Carbon savings, tax deductions, and fuel savings require validated evidence and are not calculated here. Donation exports are demo records, not tax receipts.</div>`}
const titles={overview:['Overview','Every recovery starts with a better connection.'],surplus:['Surplus marketplace','Give good food its next destination.'],recovery:['Recovery switchboard','Monitor the window. Switch while there is still time.'],bins:['Smart bins','Know what is ready, before a truck leaves.'],haul:['Hauler routes','One coordinated run. More material recovered.'],demand:['Demand alerts','Connect available food with community needs.'],impact:['Impact & activity','Track the outcomes of your demo session.']};
function render(){if(!titles[state.view])state.view='overview';save();const [title,desc]=titles[state.view];const navigation=[['overview','grid','Overview'],['surplus','box','Surplus marketplace'],['recovery','route','Recovery switchboard'],['bins','bin','Smart bins'],['haul','truck','Hauler routes'],['demand','bell','Demand alerts'],['impact','chart','Impact & activity']];$('#app').innerHTML=`<div class="shell"><aside class="sidebar"><div class="brand"><span class="brandmark">${icon('leaf')}</span><span class="brand-text">ResQ-Haul<span style="color:#8bae56">.</span></span></div><div class="brand-sub">RECOVER. REROUTE. RENEW.</div><div class="nav-label">Workspace</div><nav aria-label="Main navigation">${navigation.map(([v,ic,t])=>`<button title="${t}" data-view="${v}" class="${state.view===v?'active':''}" ${state.view===v?'aria-current="page"':''}>${icon(ic)}<span>${t}</span>${v==='bins'&&totals().ready?`<span class="count">${totals().ready}</span>`:''}</button>`).join('')}</nav><div class="sidebar-bottom"><div class="pilot"><strong>${icon('leaf')} Kuala Lumpur pilot</strong><p>A connected future for food, communities, and the city.</p><span class="badge" style="margin-top:12px">CIC Asia 2026 · Demo</span></div><div class="profile"><div class="avatar">AK</div><div><strong>Aminah & Raju</strong><small>Demo operations workspace</small></div></div></div></aside><main class="main"><header class="topbar"><div class="location">${icon('pin')}<strong>Kuala Lumpur</strong><span style="color:#bcc3b6">/</span><span>Operations</span></div><div class="topright"><span class="date">Demo clock · +${state.elapsed} min</span><span class="demo-pill">Interactive demo</span><button class="ghost small" title="Demand alerts" data-view="demand">${icon('bell')}</button></div></header><div class="content"><div class="heading"><div><h1>${title}</h1><p class="sub">${desc}</p></div><div class="actions"><button data-action="advance">${icon('clock')} Advance 15 min</button>${state.view==='overview'||state.view==='surplus'?`<button class="primary" data-action="new">${icon('plus')} List surplus</button>`:`<button class="small" data-action="reset">${icon('reset')} Reset demo</button>`}</div></div>${({overview,surplus,recovery,bins,haul,demand,impact}[state.view])()}<div class="footer-note">ResQ-Haul · Demonstration data · Simulated routing, sensors & transactions · Saved on this device <button class="textlink" data-action="guide" style="margin-left:10px">Demo guide</button></div></div></main></div>`}
function openDialog(html){$('#dialog').innerHTML=html;$('#dialog').showModal()}
function closeDialog(){$('#dialog').close()}
function newListing(){openDialog(`<div class="dialog-head"><h2>Give surplus a second chance</h2><button class="ghost small" data-action="close" aria-label="Close dialog">${icon('close')}</button></div><form id="listing-form"><div class="form-grid"><label>Food name<input name="name" placeholder="e.g. Freshly cooked rice" maxlength="70" required></label><label>Category<select name="type"><option>Rice</option><option>Bread</option><option>Vegetables</option><option>Meals</option><option>Other</option></select></label><label>Quantity (kg)<input name="qty" type="number" min="0.1" max="100" step="0.1" value="10" required></label><label>Recovery window (minutes)<input name="window" type="number" min="5" max="1440" value="65" required></label><label>Kitchen / source<input name="source" value="Dapur Aminah" maxlength="70" required></label><label>Storage condition<select name="storage"><option>Hot-held; operator verified</option><option>Chilled</option><option>Ambient; packed</option></select></label><label>Preferred pathway<select name="mode" id="listing-mode"><option>Donate</option><option>Sell</option></select></label><label>Total price (RM)<input name="price" id="listing-price" type="number" min="1" step="0.01" value="25" disabled></label></div><p class="notice">Enter an operator-approved recovery window. The prototype does not infer safe storage times from food type.</p><div class="dialog-actions"><button type="button" data-action="close">Cancel</button><button class="primary">Create listing</button></div></form>`)}
function advance(){state.elapsed+=15;let expired=0;state.items.forEach(i=>{if(active(i)&&remaining(i)===0){i.status='Waste';expired++;log(`${i.name} expired. Edible recovery closed; physical bin transfer required.`)}});render();notify(expired?`${expired} listing(s) moved to the waste transfer queue.`:'Demo clock advanced by 15 minutes. Recovery windows updated.')}
function routeOrder(bins){let p={x:70,y:310},pending=[...bins],ids=[];while(pending.length){pending.sort((a,b)=>Math.hypot(a.x-p.x,a.y-p.y)-Math.hypot(b.x-p.x,b.y-p.y));p=pending.shift();ids.push(p.id)}return ids}
document.addEventListener('click',e=>{const b=e.target.closest('button');if(!b||b.disabled)return;if(b.dataset.view){nav(b.dataset.view);return}if(b.dataset.filter){state.filter=b.dataset.filter;render();return}const id=Number(b.dataset.id),i=selected();switch(b.dataset.action){case 'close':closeDialog();break;case 'new':newListing();break;case 'advance':advance();break;case 'inspect':state.selected=id;nav('recovery');break;case 'reserve':if(viable(i)){i.status='Reserved';log(`${i.name} reserved for ${i.recipient}.`);render();notify('Demo reservation confirmed. Complete the handover when received.')}break;case 'handover':if(i.status==='Reserved'&&viable(i)){i.status='Recovered';log(`${i.qty} kg of ${i.name} recovered via ${i.recipient}.`);render();notify('Handover recorded. Impact totals updated.')}break;case 'switch':{const d=Number(b.dataset.distance),cap=Number(b.dataset.capacity);if(viable(i,d,true)&&i.qty<=cap){i.recipient=b.dataset.name;i.mode='Donate';i.price=0;i.switched=true;i.status='Reserved';state.distance=d;state.delay=0;log(`${i.name} switched to ${i.recipient}; donation reserved.`);render();notify('Alternative pathway reserved. Pickup delay reset for the new driver.')}break}case 'fill':{const bin=state.bins.find(x=>x.id===id),prev=bin.fill;bin.fill=Math.min(100,bin.fill+10);if(prev<90&&bin.fill>=90)log(`${bin.name} crossed the 90% collection threshold.`);render();notify('Simulated sensor reading updated.');break}case 'transfer':{const item=state.items.find(x=>x.id===id);if(item.status!=='Waste')break;const bin=state.bins.find(x=>x.name===item.source)||state.bins[0];if(bin.fill+item.qty>100){notify(`${bin.name} has insufficient capacity. Complete a collection run first.`);break}bin.fill+=item.qty;item.status='In bin';log(`${item.qty} kg transferred to ${bin.name} bin by staff.`);render();notify('Physical transfer confirmed; bin reading updated.');break}case 'optimize':state.route=routeOrder(state.bins.filter(x=>x.fill>=90));log(`Collection route generated for ${state.route.length} eligible bins.`);render();notify('Collection sequence generated. Bins below 90% skipped.');break;case 'collect':if(state.route.length){const load=state.route.reduce((a,id)=>a+state.bins.find(x=>x.id===id).fill,0);state.route.forEach(id=>state.bins.find(x=>x.id===id).fill=0);state.collected+=load;state.completedRoutes++;log(`${load.toFixed(1)} kg delivered to the demo BSFL facility.`);state.route=[];render();notify('Collection and facility delivery recorded. Bin levels reset.')}break;case 'remove-need':state.needs=state.needs.filter(n=>n!==b.dataset.name);render();break;case 'export':{const csvCell=x=>'"'+String(x).replace(/^[=+@-]/,"'").replaceAll('"','""')+'"';const rows=[['DEMO RECORDS - NOT TAX RECEIPTS'],['Food','Quantity kg','Pathway','Status','Recipient','RM'],...state.items.map(x=>[x.name,x.qty,x.mode,x.status,x.recipient,x.status==='Recovered'&&x.mode==='Sell'?x.price:0])];const blob=new Blob(['\ufeff'+rows.map(r=>r.map(csvCell).join(',')).join('\r\n')],{type:'text/csv;charset=utf-8'});const a=document.createElement('a');a.href=URL.createObjectURL(blob);a.download='resq-haul-demo-records.csv';a.click();setTimeout(()=>URL.revokeObjectURL(a.href),1000);notify('Demo records exported.');break}case 'reset':openDialog(`<h2>Reset the demo?</h2><p>This removes your demo listings, collections, and actions from this browser and restores the sample data.</p><div class="dialog-actions"><button data-action="close">Keep working</button><button class="primary" data-action="confirm-reset">Reset demo</button></div>`);break;case 'confirm-reset':state=initial();closeDialog();render();notify('Demo restored.');break;case 'guide':openDialog(`<div class="dialog-head"><h2>Your five-minute walkthrough</h2><button class="ghost small" data-action="close" aria-label="Close">${icon('close')}</button></div><div class="steps"><div class="step"><span class="step-number">1</span><div><h3>List & match</h3><p>Create rice or bread surplus, then open Demand alerts to see the match.</p></div></div><div class="step"><span class="step-number">2</span><div><h3>Simulate a delay</h3><p>Open Recovery switchboard. Set pickup delay to 45 min. Watch the route become blocked and the radius shrink.</p></div></div><div class="step"><span class="step-number">3</span><div><h3>Switch & recover</h3><p>Switch to Neighbourhood food hub, then confirm handover. Check Impact & activity.</p></div></div><div class="step"><span class="step-number">4</span><div><h3>Close the loop</h3><p>Advance time until another listing expires. In Smart bins, confirm the physical transfer when space permits. Generate and complete a Hauler route.</p></div></div></div><button class="primary full" data-action="close">Explore the demo</button>`);break}});
document.addEventListener('change',e=>{if(['distance','traffic','temp','delay'].includes(e.target.id)){state[e.target.id]=Number(e.target.value);render()}if(e.target.id==='item-select'){state.selected=Number(e.target.value);render()}if(e.target.id==='listing-mode'){$('#listing-price').disabled=e.target.value!=='Sell';$('#listing-price').required=e.target.value==='Sell'}});
document.addEventListener('input',e=>{if(e.target.id==='search'){state.search=e.target.value;const items=state.items.filter(i=>(state.filter==='All'||i.mode===state.filter||i.status===state.filter)&&(i.name+' '+i.source).toLowerCase().includes(state.search.toLowerCase()));$('#results').innerHTML=table(items)}});
document.addEventListener('submit',e=>{e.preventDefault();const f=new FormData(e.target);if(e.target.id==='listing-form'){const qty=Number(f.get('qty')),windowMin=Number(f.get('window'));if(!(qty>0&&qty<=100&&windowMin>=5))return;const type=f.get('type'),item={id:Math.max(...state.items.map(x=>x.id))+1,name:f.get('name').trim(),qty,source:f.get('source').trim(),area:'Kuala Lumpur',type,mode:f.get('mode'),price:f.get('mode')==='Sell'?Number(f.get('price')):0,deadline:state.elapsed+windowMin,symbol:({Rice:'🍚',Bread:'🥖',Vegetables:'🥬',Meals:'🥡'})[type]||'📦',status:'Available',recipient:f.get('mode')==='Sell'?'Consumer pickup':'Community kitchen',storage:f.get('storage'),switched:false};if(!item.name||!item.source)return;state.items.unshift(item);state.selected=item.id;log(`${item.qty} kg of ${item.name} listed for ${item.mode.toLowerCase()}.`);closeDialog();render();notify(state.needs.includes(type)?'Listing created. A matching community demand alert is available.':'Surplus listing created.')}if(e.target.id==='needs-form'){const n=f.get('need');if(!state.needs.includes(n)){state.needs.push(n);log(`Demand alert added for ${n.toLowerCase()}.`)}render();notify('Demand preferences updated.')}});
render();
